import { createHash } from "crypto";

export interface FeedNode {
  id: string;
  url: string;
}

interface VNode {
  point: number;
  node: FeedNode;
}

function hash32(input: string): number {
  return createHash("sha1").update(input).digest().readUInt32BE(0);
}

export class HashRing {
  private vnodes: VNode[] = [];

  constructor(nodes: FeedNode[], private readonly replicas = 128) {
    for (const n of nodes) this.add(n);
  }

  add(node: FeedNode): void {
    for (let i = 0; i < this.replicas; i++) {
      this.vnodes.push({ point: hash32(`${node.id}:${i}`), node });
    }
    this.vnodes.sort((a, b) => a.point - b.point);
  }

  remove(nodeId: string): void {
    this.vnodes = this.vnodes.filter((v) => v.node.id !== nodeId);
  }

  locate(key: string): FeedNode {
    if (this.vnodes.length === 0) throw new Error("ring is empty");
    const h = hash32(key);
    let lo = 0;
    let hi = this.vnodes.length;
    while (lo < hi) {
      const mid = (lo + hi) >>> 1;
      if (this.vnodes[mid].point < h) lo = mid + 1;
      else hi = mid;
    }
    if (lo === this.vnodes.length) return this.vnodes[this.vnodes.length - 1].node;
    return this.vnodes[lo].node;
  }
}

import { HashRing, FeedNode } from "./hashRing";

export interface Post {
  id: string;
  authorId: string;
  text: string;
  createdAt: number;
}

export interface FeedStoreClient {
  appendPost(node: FeedNode, post: Post): Promise<void>;
  recentPosts(node: FeedNode, authorIds: string[], limit: number): Promise<Post[]>;
}

export class TimelineService {
  constructor(
    private readonly ring: HashRing,
    private readonly store: FeedStoreClient,
  ) {}

  async publish(post: Post): Promise<void> {
    const node = this.ring.locate(post.authorId);
    await this.store.appendPost(node, post);
  }

  async homeTimeline(following: string[], limit = 30): Promise<Post[]> {
    const byNode = new Map<string, { node: FeedNode; authors: string[] }>();
    for (const authorId of following) {
      const node = this.ring.locate(authorId);
      const entry = byNode.get(node.id) ?? { node, authors: [] };
      entry.authors.push(authorId);
      byNode.set(node.id, entry);
    }

    const batches = await Promise.all(
      [...byNode.values()].map(({ node, authors }) =>
        this.store.recentPosts(node, authors, limit),
      ),
    );

    return batches
      .flat()
      .sort((a, b) => b.createdAt - a.createdAt || (a.id < b.id ? 1 : -1))
      .slice(0, limit);
  }
}
